def canonical(obj):return json.dumps(obj,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def sha(raw):return hashlib.sha256(raw).hexdigest()
def read_direct(p):
 p=Path(p);assert str(p) in PINS;assert stat.S_ISREG(p.lstat().st_mode);raw=p.read_bytes();assert sha(raw)==PINS[str(p)];return raw
def reference(p,**extra):
 p=Path(p);return {'path':str(p),'file_sha256':sha(p.read_bytes()),**extra}
def lines(p,lo,hi):
 raw=read_direct(p).decode().splitlines();assert 1<=lo<=hi<=len(raw);return reference(p,start_line=lo,end_line=hi,excerpt='\n'.join(raw[lo-1:hi]))
def objref(p,pointer):return reference(p,pointer=pointer)
def save(name,obj):(OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
